// ---- CONFIG: edit these, or set as Node-RED env vars with the same names ----
const ERP_BASE_URL = env.get('ERP_BASE_URL') || 'http://frontend:8080';
const ERP_API_KEY = env.get('ERP_API_KEY') || 'YOUR_ERPNEXT_API_KEY';
const ERP_API_SECRET = env.get('ERP_API_SECRET') || 'YOUR_ERPNEXT_API_SECRET';
const DEFAULT_WAREHOUSE = env.get('ERP_DEFAULT_WAREHOUSE') || 'Stores - SD';

msg.erp = {
    baseUrl: ERP_BASE_URL,
    authHeader: 'token ' + ERP_API_KEY + ':' + ERP_API_SECRET
};

// ---- CSV ROW MAPPING ----
// TODO: once the supplier's real CSV headers are known, update the
// row.xxx field names below to match them exactly (case-sensitive).
const map = msg.dynamicMapping;
const row = msg.payload;

if (!map) {
    node.warn('No mapping available for this row - skipping');
    return null;
}

msg.item = {
    item_code: row[map.item_code],
    csv_qty: Number(row[map.qty]),
    warehouse: (map.warehouse && row[map.warehouse]) || DEFAULT_WAREHOUSE
};


if (!msg.item.item_code || isNaN(msg.item.csv_qty)) {
    node.warn('Skipping row with missing item_code or invalid qty: ' + JSON.stringify(row));
    return null;
}

return msg;

const filters = JSON.stringify([["item_code", "=", msg.item.item_code], ["warehouse", "=", msg.item.warehouse]]);
const fields = JSON.stringify(["actual_qty"]);

msg.url = `${msg.erp.baseUrl}/api/resource/Bin?filters=${encodeURIComponent(filters)}&fields=${encodeURIComponent(fields)}`;
msg.method = 'GET';
msg.headers = { 'Authorization': msg.erp.authHeader };
return msg;

const currentQty = (msg.payload && msg.payload.data && msg.payload.data.length > 0)
    ? Number(msg.payload.data[0].actual_qty) : 0;

const delta = msg.item.csv_qty - currentQty;
msg.item.currentQty = currentQty;
msg.item.delta = delta;
msg.item.absQty = Math.abs(delta);
msg.item.entryType = delta >= 0 ? 'Material Receipt' : 'Material Issue';

return msg;

msg.url = `${msg.erp.baseUrl}/api/resource/Item/${encodeURIComponent(msg.item.item_code)}`;
msg.method = 'GET';
msg.headers = { 'Authorization': msg.erp.authHeader };
return msg;

// TODO: set real defaults for your item master before relying on auto-create
msg.url = `${msg.erp.baseUrl}/api/resource/Item`;
msg.method = 'POST';
msg.headers = { 'Authorization': msg.erp.authHeader, 'Content-Type': 'application/json' };
msg.payload = {
    item_code: msg.item.item_code,
    item_name: msg.item.item_code,
    item_group: 'All Item Groups',
    stock_uom: 'Nos'
};
return msg;

const it = msg.item;
const body = {
    stock_entry_type: it.entryType,
    items: [
        {
            item_code: it.item_code,
            qty: it.absQty
        }
    ]
};

if (it.entryType === 'Material Receipt') {
    body.items[0].t_warehouse = it.warehouse;
} else {
    body.items[0].s_warehouse = it.warehouse;
}

msg.url = `${msg.erp.baseUrl}/api/resource/Stock Entry`;
msg.method = 'POST';
msg.headers = { 'Authorization': msg.erp.authHeader, 'Content-Type': 'application/json' };
msg.payload = body;
return msg;

if (!msg.payload || !msg.payload.data || !msg.payload.data.name) {
    msg.payload = 'ERROR creating Stock Entry for ' + msg.item.item_code + ': ' + JSON.stringify(msg.payload);
    return [null, msg];
}

msg.entryName = msg.payload.data.name;
msg.url = `${msg.erp.baseUrl}/api/resource/Stock Entry/${encodeURIComponent(msg.entryName)}`;
msg.method = 'PUT';
msg.headers = { 'Authorization': msg.erp.authHeader, 'Content-Type': 'application/json' };
msg.payload = { docstatus: 1 };
return [msg, null];

const stdout = (msg.payload ? msg.payload.toString() : '').trim();
const files = stdout ? stdout.split('\n').map(f => f.trim()).filter(Boolean) : [];

let processed = flow.get('processedCsvFiles') || [];
const newFiles = files.filter(f => !processed.includes(f));

if (newFiles.length === 0) {
    return null;
}

processed = processed.concat(newFiles);
flow.set('processedCsvFiles', processed);

return [ newFiles.map(f => ({ payload: f })) ];

msg.rawCsv = msg.payload;
const lines = msg.rawCsv.split('\n').filter(Boolean);
const headerLine = lines[0];
const sampleLine = lines[1] || '';
const prompt =`Here are column headers from a supplier's raw material delivery CSV, plus one sample data row.

Headers: ${headerLine}
Sample row: ${sampleLine}

Map these headers to these canonical fields: item_code (the material/product code), qty (quantity received), warehouse (destination warehouse, if present).

Respond ONLY with a raw JSON object, no markdown, no explanation, in exactly this shape:
{"item_code": "<header name>", "qty": "<header name>", "warehouse": "<header name or null>"}`;
const GEMINI_API_KEY = env.get('GEMINI_API_KEY') || 'REPLACE_YOUR_GEMINI_API_KEY';
msg.url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent';
msg.method = 'POST';
msg.headers = {
    'x-goog-api-key': GEMINI_API_KEY,
    'content-type' : 'application/json'
};
msg.payload = {
    contents: [{ parts: [{ text: prompt }] }]
};

return msg;

try {
    const text = msg.payload.candidates[0].content.parts[0].text.trim();
    const cleaned = text.replace(/```json|```/g, '').trim();
    msg.dynamicMapping = JSON.parse(cleaned);
} catch (e) {
    node.warn('Failed to parse Gemini header mapping: ' + JSON.stringify(msg.payload));
    return null; // don't process this file with a broken mapping
}

msg.payload = msg.rawCsv; // restore the original CSV text
return msg;
